// @ts-check
import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import prettier from 'eslint-config-prettier';

export default tseslint.config(
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/.next/**',
      '**/coverage/**',
      '**/storage/**',
      '**/*.config.js',
      '**/*.config.mjs',
      'apps/api/prisma/migrations/**',
      // Generated by Next on every build.
      'apps/web/next-env.d.ts',
    ],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    languageOptions: {
      ecmaVersion: 2023,
      sourceType: 'module',
      globals: {
        process: 'readonly',
        console: 'readonly',
        Buffer: 'readonly',
        __dirname: 'readonly',
        setTimeout: 'readonly',
        clearTimeout: 'readonly',
        setInterval: 'readonly',
        clearInterval: 'readonly',
        fetch: 'readonly',
        AbortController: 'readonly',
        AbortSignal: 'readonly',
        URL: 'readonly',
        URLSearchParams: 'readonly',
        TextEncoder: 'readonly',
        TextDecoder: 'readonly',
        crypto: 'readonly',
      },
    },
    rules: {
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' },
      ],
      '@typescript-eslint/no-explicit-any': 'warn',
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
      ],
      // See the API override below: this rule is unsafe where NestJS relies on
      // `emitDecoratorMetadata`.
      'no-console': ['error', { allow: ['warn', 'error'] }],
      eqeqeq: ['error', 'smart'],
      'no-restricted-syntax': [
        'error',
        {
          selector: "CallExpression[callee.name='eval']",
          message: 'eval() is not permitted.',
        },
      ],
    },
  },
  // `consistent-type-imports` is actively harmful in the API.
  //
  // NestJS resolves constructor dependencies from `design:paramtypes`, which
  // `emitDecoratorMetadata` only emits for classes imported in *value* position.
  // Rewriting `import { AppConfig }` to `import { type AppConfig }` erases the
  // class at compile time, the metadata degrades to `Function`, and every
  // affected provider fails to resolve at boot — with an error that points at the
  // injection site rather than at the import. It compiles and it type-checks; it
  // just does not run. So the rule is off here, deliberately.
  {
    files: ['apps/api/src/**/*.ts'],
    rules: {
      '@typescript-eslint/consistent-type-imports': 'off',
    },
  },

  // Architectural boundaries.
  //  * Business logic must not reach for vendor SDKs — that is what the provider
  //    adapters under src/providers are for.
  //  * Process spawning is confined to the ffmpeg service.
  // Both live in one block because ESLint flat config resolves a rule by
  // "last matching block wins" rather than by merging its options.
  {
    files: ['apps/api/src/**/*.ts'],
    ignores: ['apps/api/src/infrastructure/ffmpeg/**'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            {
              name: 'node:child_process',
              message: 'Process spawning is confined to infrastructure/ffmpeg.',
            },
            {
              name: 'child_process',
              message: 'Process spawning is confined to infrastructure/ffmpeg.',
            },
          ],
        },
      ],
    },
  },
  {
    files: ['apps/api/src/modules/**/*.ts'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            { name: 'googleapis', message: 'Use the YouTubeProvider port instead.' },
            { name: 'openai', message: 'Use the LLMProvider port instead.' },
            { name: '@anthropic-ai/sdk', message: 'Use the LLMProvider port instead.' },
            { name: '@google-cloud/storage', message: 'Use the StorageProvider port instead.' },
            { name: '@google-cloud/tasks', message: 'Use the QueueProvider port instead.' },
            {
              name: 'node:child_process',
              message: 'Process spawning is confined to infrastructure/ffmpeg.',
            },
            {
              name: 'child_process',
              message: 'Process spawning is confined to infrastructure/ffmpeg.',
            },
          ],
          patterns: [
            {
              group: ['**/providers/**/*.provider'],
              message: 'Inject the provider port via its DI token; never import an adapter.',
            },
          ],
        },
      ],
    },
  },
  // Seed and maintenance scripts are CLIs: printing progress is their interface.
  {
    files: ['apps/api/prisma/seed.ts', 'scripts/**/*.ts', 'scripts/**/*.mjs'],
    rules: { 'no-console': 'off' },
  },
  {
    files: ['**/*.spec.ts', '**/*.test.ts', '**/test/**/*.ts'],
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-non-null-assertion': 'off',
      'no-console': 'off',
    },
  },
  prettier,
);
